mapper.select:
select fulldata.O_CODE, fulldata.O_TYPE, fulldata.GRADE_ORG_ID, fulldata.GRADE_DATE, MAPP.GRADE_STANDARD_RESULT AS RATING from MST_BOND_CREDIT_RATING fulldata inner join ( SELECT MBCR.O_CODE AS O_CODE, MBCR.O_TYPE AS O_TYPE, MBCR.GRADE_ORG_ID AS GRADE_ORG_ID, max(MBCR.GRADE_DATE) AS GRADE_DATE FROM MST_BOND_CREDIT_RATING MBCR WHERE 1 = 1
AND MBCR.O_CODE = #{ocode,jdbcType=VARCHAR}
AND MBCR.O_TYPE = #{otype,jdbcType=VARCHAR}
AND MBCR.GRADE_ORG_ID = #{gradeorgid,jdbcType=VARCHAR}
group by O_CODE, O_TYPE, GRADE_ORG_ID, GRADE_DATE ) maxdata on fulldata.O_CODE = maxdata.O_CODE and fulldata.O_TYPE = maxdata.O_TYPE and fulldata.GRADE_ORG_ID = maxdata.GRADE_ORG_ID inner join MOD_STANDARD_GRADE_MAPPING MAPP ON fulldata.GRADE_ORG_ID = MAPP.GRADE_INST /**评级机构**/ AND fulldata.O_TYPE = MAPP.O_TYPE /**评级类型**/ AND fulldata.GRADE_RESULT = MAPP.GRADE_RESULT /**评级结果**/
